import React, { useEffect, useRef, useState } from 'react';
import { Loader2, ShieldCheck, XCircle } from 'lucide-react';
import { useLocation } from 'react-router-dom';
import { SEO } from '../components/SEO';
import {
  buildCentralAuthRetryUrl,
  createCentralAuthStartUrl,
  finishCentralAuthHandoff,
} from '../lib/authHandoff';
import { resolveAuthReturnUrl } from '../lib/authRouting';

const AuthStateShell = ({ error, retryUrl }: { error?: string | null; retryUrl?: string }) => (
  <div className="grid min-h-[100dvh] place-items-center bg-[#050505] px-6 text-center text-white">
    <SEO title={error ? 'Sign-in handoff failed' : 'Securing your session'} noIndex />
    <div className="w-full max-w-md rounded-[2rem] border border-white/10 bg-white/[0.035] p-8 shadow-2xl">
      <div className={`mx-auto grid h-16 w-16 place-items-center rounded-2xl border ${error ? 'border-red-400/20 bg-red-500/10 text-red-300' : 'border-indigo-300/20 bg-indigo-500/10 text-indigo-200'}`}>
        {error ? <XCircle className="h-7 w-7" /> : <ShieldCheck className="h-7 w-7" />}
      </div>
      <h1 className="mt-6 text-2xl font-bold tracking-tight">{error ? 'We could not finish signing you in' : 'Securing your Wersee session'}</h1>
      <p className="mt-3 text-sm leading-6 text-white/50">{error || 'One moment while Wersee completes the protected handoff to the correct site.'}</p>
      {!error && <Loader2 className="mx-auto mt-6 h-5 w-5 animate-spin text-white/60" />}
      {error && <a href={retryUrl || '/auth/begin'} className="mt-6 inline-flex rounded-full bg-white px-5 py-3 text-sm font-bold text-black">Try again</a>}
    </div>
  </div>
);

export const AuthHandoffBegin = ({ authPath }: { authPath?: string }) => {
  const location = useLocation();
  const [error, setError] = useState<string | null>(null);
  const startedRef = useRef(false);

  useEffect(() => {
    if (startedRef.current) return;
    startedRef.current = true;
    let active = true;
    const searchParams = new URLSearchParams(location.search);
    const returnUrl = resolveAuthReturnUrl(
      searchParams.get('returnUrl') || searchParams.get('returnTo') || searchParams.get('redirect'),
    );
    const requestedPath = authPath || searchParams.get('authPath') || '/auth';
    const sourceParams = new URLSearchParams(location.search);
    sourceParams.delete('authPath');
    const separator = requestedPath.includes('?') ? '&' : '?';
    const destinationPath = sourceParams.size
      ? `${requestedPath}${separator}${sourceParams.toString()}`
      : requestedPath;

    void createCentralAuthStartUrl(destinationPath, returnUrl)
      .then((url) => { if (active) window.location.replace(url); })
      .catch((caught: unknown) => {
        if (active) setError(caught instanceof Error ? caught.message : 'Could not start secure sign-in.');
      });
    return () => { active = false; };
  }, [authPath, location.search]);

  return <AuthStateShell error={error} retryUrl={buildCentralAuthRetryUrl()} />;
};

export const AuthHandoff = () => {
  const location = useLocation();
  const [error, setError] = useState<string | null>(null);
  const startedRef = useRef(false);
  const retryUrlRef = useRef(buildCentralAuthRetryUrl());

  useEffect(() => {
    if (startedRef.current) return;
    startedRef.current = true;
    let active = true;
    const searchParams = new URLSearchParams(location.search);
    void finishCentralAuthHandoff(searchParams)
      .then((returnUrl) => { if (active) window.location.replace(returnUrl); })
      .catch((caught: unknown) => {
        if (active) setError(caught instanceof Error ? caught.message : 'Could not finish secure sign-in.');
      });
    return () => { active = false; };
  }, [location.search]);

  return <AuthStateShell error={error} retryUrl={retryUrlRef.current} />;
};
